package com.hmdp.ai.domain.knowledge;
public final class KnowledgeBase {private final String id,tenantId,workspaceId,code,name,description,status;private final int latestVersion;public KnowledgeBase(String id,String tenantId,String workspaceId,String code,String name,String description,int latestVersion,String status){this.id=id;this.tenantId=tenantId;this.workspaceId=workspaceId;this.code=code;this.name=name;this.description=description;this.latestVersion=latestVersion;this.status=status;}public String getId(){return id;}public String getTenantId(){return tenantId;}public String getWorkspaceId(){return workspaceId;}public String getCode(){return code;}public String getName(){return name;}public String getDescription(){return description;}public int getLatestVersion(){return latestVersion;}public String getStatus(){return status;}}
